<main class="cp-main cp-services"><section class="cp-products__header"><div><p class="cp-eyebrow cp-eyebrow--dark"><span></span> Website content</p><h1>Reviews & Feedback</h1></div><button class="cp-add-product" id="review-open"><span>+</span> Add review</button></section>@if($reviews->isEmpty())<section class="cp-gallery-empty"><span>&#9733;</span><h2>No reviews yet</h2><p>Add your first customer review or feedback.</p><button class="cp-add-product" type="button" onclick="document.getElementById('review-open').click()"><span>+</span> Add review</button></section>@else<section class="cp-service-grid">@foreach($reviews as $r)<article class="cp-service-card">@if($r->image)<img src="/{{ ltrim($r->image, '/') }}" alt="{{ $r->name }}">@else<div class="cp-service-card__placeholder cp-review-placeholder">{{ strtoupper(substr($r->name,0,1)) }}</div>@endif<div class="cp-service-card__body"><span class="cp-service-card__position">{{ str_repeat('★',$r->rating) }}</span><h2>{{ $r->name }}</h2><p>{{ $r->designation }}<br>{{ $r->message }}</p><div class="cp-service-card__actions"><button type="button" class="review-edit" data-id="{{ $r->id }}" data-name="{{ $r->name }}" data-designation="{{ $r->designation }}" data-rating="{{ $r->rating }}" data-message="{{ $r->message }}">Edit</button><button class="delete-btn" data-id="{{ $r->id }}" data-url="{{ route('panel.pnc-reviews.delete',$r->id) }}">Delete</button></div></div></article>@endforeach</section>@endif</main>
<div class="service-modal" id="review-modal"><div class="service-modal__backdrop" id="review-close"></div><section class="service-modal__dialog"><header><h2>Add review</h2><button class="ws-modal__close" id="review-x">&times;</button></header><form action="{{route('panel.pnc-reviews.store')}}" method="POST" enctype="multipart/form-data">@csrf<div class="ws-grid"><label>Name<input name="name" required></label><label>Designation<input name="designation"></label><label>Reviewer image<input type="file" name="image" accept=".jpg,.jpeg,.png,.webp"></label><label>Rating<select name="rating">@for($i=5;$i>=1;$i--)<option value="{{$i}}">{{$i}} stars</option>@endfor</select></label><label class="ws-span-2">Feedback<textarea name="message" required rows="4"></textarea></label></div><footer><button class="cp-add-product">Save review</button></footer></form></section></div><script>document.addEventListener('DOMContentLoaded',function(){let m=document.getElementById('review-modal');document.getElementById('review-open').onclick=()=>m.classList.add('is-open');document.querySelectorAll('.review-edit').forEach(b=>b.onclick=()=>{let f=m.querySelector('form');f.action='{{ url('/panel/user/reviews') }}/'+b.dataset.id;f.name.value=b.dataset.name;f.designation.value=b.dataset.designation;f.rating.value=b.dataset.rating;f.message.value=b.dataset.message;m.classList.add('is-open')});document.getElementById('review-close').onclick=()=>m.classList.remove('is-open');document.getElementById('review-x').onclick=()=>m.classList.remove('is-open')})</script>
